(r"/^(Ambuklao|Binga|San Roque) sits$/", "Ang $1 ay", "Ti $1 ket"),
(r"/^below normal high water$/", "mas mababa sa normal high water", "nababbaba ngem normal high water"),
(r"/^Rain, (.+)$/", "Ulan, $1", "Tudo, $1"),
