(r"/^(\w+ \d{4}): no dry stage listed$/", "$1: walang nakalistang dry stage", "$1: awan ti nailista a dry stage"),
(r"/^(\w+ \d{4}): (Dry condition|Dry spell|Drought)$/", "$1: $2", "$1: $2"),
(r"/^(\w+ \d{4}): beyond the outlook$/", "$1: lampas sa outlook", "$1: labes iti outlook"),
(r"/^(\d{1,2} \w{3} \d{2}): (.+)$/", "$1: $2", "$1: $2"),
